#!/usr/bin/env python3
"""make.fun autonomous runner (correct flow).

For each open bounty:
  1. fetch kit, unpack
  2. `makefun init` -> entry repo (git, signed with wallet)
  3. harness (deepseek via claudepeak) implements in the entry repo
  4. `makefun check`
  5. publish entry repo to GitHub (repo_url + commit)
  6. `makefun submit` (repo_url, commit, transcript, wallet)

Usage: runner.py --list | --dry | --live
"""
import json
import pathlib
import shutil
import subprocess
import sys
import time

import requests

BASE = "/root/makefun"
ENVF = {}
for _l in open(BASE + "/runner.env"):
    _l = _l.strip()
    if _l and not _l.startswith("#") and "=" in _l:
        k, v = _l.split("=", 1)
        ENVF[k.strip()] = v.strip()
ORIGIN = ENVF.get("MAKEFUN_ORIGIN", "https://make.fun")
MFKEY = ENVF.get("MAKEFUN_API_KEY", "")
HARNESS = ENVF.get("HARNESS_CMD", "")
HARNESS_MODEL = ENVF.get("HARNESS_MODEL", "deepseek-v4.1-flash")
HARNESS_BASE = ENVF.get("HARNESS_BASE", "https://api.claudepeak.com/v1")
WALLET = BASE + "/wallet.json"
MAX_PER_RUN = int(ENVF.get("MAX_PER_RUN", "3"))
TG = ENVF.get("TELEGRAM_BOT_TOKEN", "")
CHAT = ENVF.get("TELEGRAM_CHAT_ID", "")
STATE = BASE + "/state.json"
WORK = pathlib.Path(BASE + "/work")
ENTRIES = pathlib.Path(BASE + "/entries")
LIVE = "--live" in sys.argv

PROMPT = """You are an autonomous coding agent competing on make.fun.
Bounty: {slug}
Requirements: {req}

Implement the deliverable in THIS repository (cwd). Read RULES.txt via the kit at {kit}.
Use the kit CLI (node {kit}/cli/makefun.mjs check) to validate. Keep it minimal, pass every check.
"""


def log(*a):
    print(*a, flush=True)


def notify(t):
    if TG and CHAT:
        try:
            requests.post("https://api.telegram.org/bot%s/sendMessage" % TG,
                          json={"chat_id": CHAT, "text": t[:3800]}, timeout=20)
        except Exception:
            pass


def mf_get(path):
    return requests.get(ORIGIN + path, headers={"x-api-key": MFKEY}, timeout=60)


def load_state():
    try:
        return json.load(open(STATE))
    except Exception:
        return {}


def save_state(s):
    json.dump(s, open(STATE, "w"))


def list_open():
    items, cur = [], None
    while True:
        d = mf_get("/api/competitions?status=open" + (("&cursor=" + cur) if cur else "")).json()
        items += d.get("items", [])
        cur = d.get("next_cursor")
        if not cur:
            break
    return items


def fetch_kit(slug, dest):
    r = requests.get(ORIGIN + "/c/%s/kit" % slug, headers={"x-api-key": MFKEY}, timeout=180)
    r.raise_for_status()
    tar = dest / "kit.tar.gz"
    tar.write_bytes(r.content)
    subprocess.run(["tar", "xzf", str(tar), "-C", str(dest)], check=True)


def find_kit_root(d):
    for p in d.iterdir():
        if p.is_dir() and (p / "cli" / "makefun.mjs").exists():
            return p
    for p in d.rglob("cli/makefun.mjs"):
        return p.parent.parent
    return d


def run(cmd, cwd, timeout):
    return subprocess.run(["bash", "-lc", cmd], cwd=str(cwd), capture_output=True, text=True, timeout=timeout)


def work_bounty(slug, st):
    d = WORK / slug
    d.mkdir(parents=True, exist_ok=True)
    if not (d / "kit.json").exists():
        fetch_kit(slug, d)
    kit = find_kit_root(d)
    req = mf_get("/api/competitions/%s/requirements" % slug).json()

    entry = ENTRIES / slug
    if entry.exists():
        shutil.rmtree(entry)
    entry.mkdir(parents=True)
    r = run("node %s init --competition %s --keypair %s" % (kit / "cli/makefun.mjs", slug, WALLET),
            entry, 300)
    log("  init:", r.returncode, r.stderr.strip()[:160])
    (entry / "PROMPT.txt").write_text(PROMPT.format(slug=slug, req=json.dumps(req)[:6000], kit=kit))
    if not LIVE:
        st[slug] = "scaffolded"
        return
    if not HARNESS:
        st[slug] = "no-harness"; return

    rh = run("source %s/env.sh && cd %s && %s" % (BASE, entry, HARNESS), BASE, 5400)
    log("  harness rc:", rh.returncode)
    rc = run("node %s check --repo %s" % (kit / "cli/makefun.mjs", entry), entry, 900)
    log("  check rc:", rc.returncode, (rc.stdout or rc.stderr).strip()[-300:])

    pub = run("%s/../venv/bin/python %s/makefun_publish.py %s %s" % (BASE, BASE, slug, entry), BASE, 300)
    log("  publish:", pub.stdout.strip()[-200:], pub.stderr.strip()[-120:])
    repo_url = commit = ""
    for line in pub.stdout.splitlines():
        if line.startswith("repo_url "):
            repo_url = line.split(" ", 1)[1].strip()
        if line.startswith("commit "):
            commit = line.split(" ", 1)[1].strip()

    if repo_url and commit:
        sub = run(
            "node %s submit --competition %s --repo-url %s --commit %s "
            "--transcript %s/transcript.json --harness direct-mistral-api --model %s --provider claudepeak "
            "--prompt-origin handed-off --instructions none --keypair %s --no-wait --api-key %s --json"
            % (kit / "cli/makefun.mjs", slug, repo_url, commit, entry, HARNESS_MODEL, WALLET, MFKEY),
            entry, 600)
        log("  submit rc:", sub.returncode, (sub.stdout or sub.stderr).strip()[-400:])
        st[slug] = "submitted" if sub.returncode == 0 else "submit-failed"
    else:
        st[slug] = "built-not-published"


def ranked(comps):
    return sorted(comps, key=lambda c: (c.get("rewardAmount") or 0), reverse=True)


def pass_once(st):
    comps = ranked(list_open())
    done = {"submitted", "built-not-published", "no-harness", "scaffolded"}
    todo = [c for c in comps if c.get("slug") and st.get(c["slug"]) not in done]
    log("open:", len(comps), "| todo:", len(todo), "| mode:", "LIVE" if LIVE else "dry")
    for c in todo[:MAX_PER_RUN]:
        slug = c["slug"]
        log(">> %s  ($%s)  %s" % (slug, c.get("rewardAmount"), str(c.get("title"))[:50]))
        try:
            work_bounty(slug, st)
        except Exception as e:
            log("  ERR", slug, str(e)[:150]); st[slug] = "error"
        save_state(st)
    return len(todo)


def main():
    st = load_state()
    if "--list" in sys.argv:
        for c in ranked(list_open()):
            print(" $%-6s %-45s %s" % (c.get("rewardAmount"), c.get("slug"), str(c.get("title"))[:45]))
        return
    if "--loop" in sys.argv:
        while True:
            try:
                n = pass_once(st)
                notify("make.fun loop: %d sisa" % n)
            except Exception as e:
                log("loop err", str(e)[:150])
            time.sleep(120 if n else 900)
    n = pass_once(st)
    notify("make.fun pass done: %d sisa" % n)


